import{_ as a,o as e,c as r,ai as d}from"./chunks/framework.ampVZV4B.js";const p=JSON.parse('{"title":"Java · 02 核心能力","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/java/02-core.md","filePath":"tech-system/backend/java/02-core.md"}'),l={name:"tech-system/backend/java/02-core.md"};function n(s,t,i,h,o,c){return e(),r("div",null,[...t[0]||(t[0]=[d(`<h1 id="java-·-02-核心能力" tabindex="-1">Java · 02 核心能力 <a class="header-anchor" href="#java-·-02-核心能力" aria-label="Permalink to “Java · 02 核心能力”">​</a></h1><blockquote><p>语言真正不同的地方：JVM、并发模型、内存与性能直觉。目标是 <strong>够交付、够排障</strong>，不当调优百科。</p></blockquote><h2 id="_1-jvm-与运行机制" tabindex="-1">1. JVM 与运行机制 <a class="header-anchor" href="#_1-jvm-与运行机制" aria-label="Permalink to “1. JVM 与运行机制”">​</a></h2><h3 id="底线-必须建立的图景" tabindex="-1">底线（必须建立的图景） <a class="header-anchor" href="#底线-必须建立的图景" aria-label="Permalink to “底线（必须建立的图景）”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.java → 编译 → .class（字节码）→ 类加载 → JVM 执行</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>            堆（对象） / 栈（帧、局部变量） / 元空间（类元数据）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li>写出问题前先分清：是 <strong>业务逻辑错了</strong>，还是 <strong>运行时（内存 / 线程 / GC）</strong> 出问题</li><li>Full GC / OOM 出现时知道：看堆？看元空间？看直接内存？看线程栈？</li></ul><h3 id="我刻意不追求" tabindex="-1">我刻意不追求 <a class="header-anchor" href="#我刻意不追求" aria-label="Permalink to “我刻意不追求”">​</a></h3><ul><li>把每一种垃圾收集器参数背成百科</li><li>没有线上证据就谈「调优专家」</li></ul><h3 id="判断" tabindex="-1">判断 <a class="header-anchor" href="#判断" aria-label="Permalink to “判断”">​</a></h3><p>面试能画图、线上能定位，就够支撑中小交付；更深的调优跟 <strong>具体故障</strong> 走。<br> 相关：<a href="/my-vitepress-site/tech-system/backend/problems/performance.html">后端问题 · 性能</a></p><hr><h2 id="_2-并发模型" tabindex="-1">2. 并发模型 <a class="header-anchor" href="#_2-并发模型" aria-label="Permalink to “2. 并发模型”">​</a></h2><p>Java 并发主流是 <strong>线程 + 共享内存</strong>（重，但匹配企业共享状态多的现实）。</p><h3 id="我常用的几块" tabindex="-1">我常用的几块 <a class="header-anchor" href="#我常用的几块" aria-label="Permalink to “我常用的几块”">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>解决什么</th><th>注意</th></tr></thead><tbody><tr><td><code>synchronized</code> / Lock</td><td>互斥</td><td>锁粒度；避免在锁内调远程</td></tr><tr><td><code>volatile</code></td><td>可见性与有序</td><td><strong>不保证</strong> <code>i++</code> 这类复合操作原子性</td></tr><tr><td>线程池 <code>ExecutorService</code></td><td>资源边界</td><td>别裸 <code>new Thread</code>；队列与拒绝策略要想清楚</td></tr><tr><td><code>ConcurrentHashMap</code> 等</td><td>并发容器</td><td>仍要理解「复合操作」是否原子</td></tr><tr><td>虚拟线程（新版本）</td><td>大量阻塞 IO</td><td>共享可变状态纪律不能松</td></tr></tbody></table><h3 id="和其它语言比" tabindex="-1">和其它语言比 <a class="header-anchor" href="#和其它语言比" aria-label="Permalink to “和其它语言比”">​</a></h3><table tabindex="0"><thead><tr><th>语言</th><th>模型</th><th>对我的启发</th></tr></thead><tbody><tr><td>Java</td><td>线程 + 共享内存</td><td>默认企业路径</td></tr><tr><td>Go</td><td>Goroutine + Channel</td><td>通信胜共享的思路可借鉴</td></tr><tr><td>Node</td><td>事件循环</td><td>单线程别堵；重活要迁出</td></tr></tbody></table><h3 id="我的用法" tabindex="-1">我的用法 <a class="header-anchor" href="#我的用法" aria-label="Permalink to “我的用法”">​</a></h3><ul><li><strong>业务默认</strong>：一请求一处理线程（容器线程）+ 必要时有界线程池</li><li><strong>复杂编排</strong>（如 AI 生成任务）：队列 + 状态机 + 重试，而不是在接口里狂开线程</li><li><strong>共享可变状态</strong>能少则少；必须共享就明确锁或单写多读</li></ul><p>相关：<a href="/my-vitepress-site/tech-system/backend/problems/concurrency.html">后端问题 · 并发</a></p><hr><h2 id="_3-内存与性能直觉" tabindex="-1">3. 内存与性能直觉 <a class="header-anchor" href="#_3-内存与性能直觉" aria-label="Permalink to “3. 内存与性能直觉”">​</a></h2><h3 id="现象-→-优先怀疑" tabindex="-1">现象 → 优先怀疑 <a class="header-anchor" href="#现象-→-优先怀疑" aria-label="Permalink to “现象 → 优先怀疑”">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>优先怀疑</th><th>第一步</th></tr></thead><tbody><tr><td>堆持续涨、频繁 Full GC</td><td>泄漏、缓存无界、大对象滞留</td><td>堆 dump / 看缓存 key 数量</td></tr><tr><td>CPU 高、RT 差</td><td>锁竞争、热循环、疯狂序列化/正则</td><td>采样线程栈</td></tr><tr><td>偶发超时</td><td>线程池打满、连接池耗尽、下游慢</td><td>看池队列与下游 RT</td></tr><tr><td>启动很慢</td><td>组件扫描过大、依赖过重、本机 IO</td><td>精简自动配置、看启动报告</td></tr></tbody></table><h3 id="原则" tabindex="-1">原则 <a class="header-anchor" href="#原则" aria-label="Permalink to “原则”">​</a></h3><ol><li><strong>先架构与 IO，再抠微语法</strong></li><li>绝对性能对多数业务系统「够用」；瓶颈常在库、网络、错误重试、N+1 SQL</li><li>缓存是把双刃剑：没有失效策略的缓存 = 定时炸弹</li></ol><hr><h2 id="_4-适合什么-不适合什么" tabindex="-1">4. 适合什么 / 不适合什么 <a class="header-anchor" href="#_4-适合什么-不适合什么" aria-label="Permalink to “4. 适合什么 / 不适合什么”">​</a></h2><table tabindex="0"><thead><tr><th>适合</th><th>不适合（对我而言）</th></tr></thead><tbody><tr><td>中长期业务系统、强协作</td><td>一天验证完的 AI 脚本（用 Python）</td></tr><tr><td>事务、规范、中间件集成</td><td>只图写起来爽的个人小工具</td></tr><tr><td>招聘友好、可维护存量</td><td>为了「新语言」重写已稳定域</td></tr><tr><td>MES / CRM / 内容生产状态机</td><td>纯 CPU 数值计算尖端场景</td></tr></tbody></table><h3 id="边界感" tabindex="-1">边界感 <a class="header-anchor" href="#边界感" aria-label="Permalink to “边界感”">​</a></h3><ul><li>需要 <strong>强事务 + 多人协作 + 长期演进</strong> → Java</li><li>需要 <strong>快速试模型 / 批处理文件</strong> → Python 旁路，结果回写 Java</li><li>需要 <strong>和前端同构的 BFF / 桌面本地服务</strong> → Node(TS)</li></ul><p>下一篇：<a href="./03-frameworks.html">03 框架与生态</a></p>`,32)])])}const m=a(l,[["render",n]]);export{p as __pageData,m as default};
